  function weaponSummary(weapon, id) {
    if (!weapon) return '';
    var translated = window.DK_THAI_WEAPON_DESCRIPTIONS && window.DK_THAI_WEAPON_DESCRIPTIONS[id];
    if (translated) return translated;
    var source = String(weapon._bundleOriginalDesc || weapon.desc || '').toLowerCase();
    var category = {
      MELEE: 'อาวุธประชิด',
      GUN: 'อาวุธปืน',
      MAGIC: 'อาวุธเวท',
      ARCHER: 'อาวุธธนู'
    }[weapon.category] || 'อาวุธ';
    var parts = [category + 'ที่สร้างความเสียหาย ' + (weapon.damage || 0)];
    if (/seek|homing|hunt|curve/.test(source)) parts.push('กระสุนติดตามเป้าหมาย');
    if (/pierc|through one|through two|through wall|ignore stone/.test(source)) parts.push('เจาะทะลุเป้าหมาย');
    if (/bounce|ricochet/.test(source)) parts.push('กระเด้งจากกำแพง');
    if (/burn|fire|ember|flame/.test(source)) parts.push('ทำให้ติดไฟ');
    if (/frost|freeze|chill|cold/.test(source)) parts.push('สร้างความเย็นหรือแช่แข็ง');
    if (/shock|lightning|thunder|electric/.test(source)) parts.push('ช็อตด้วยสายฟ้า');
    if (/explod|blast|burst|bomblet|rocket|shell/.test(source)) parts.push('สร้างการระเบิด');
    if (/return|home to the caster|backward|reverse/.test(source)) parts.push('ย้อนกลับตามเส้นทาง');
    if (/pull|drag|gravity|yank/.test(source)) parts.push('ดึงศัตรู');
    if (/reflect|erase hostile|blocking shots|destroys hostile|clears bullets|bullet-eating/.test(source)) parts.push('รับมือกระสุนศัตรูได้');
    if (/heal|restore/.test(source)) parts.push('ฟื้นทรัพยากรเมื่อทำเงื่อนไขสำเร็จ');
    if (/after|delayed|repeat|echo/.test(source)) parts.push('มีการโจมตีซ้ำแบบหน่วงเวลา');
    if (/hold|full draw|perfect draw|perfect release/.test(source)) parts.push('ชาร์จเพื่อเปลี่ยนรูปแบบการโจมตี');
    if (parts.length === 1) parts.push('มีกลไกการโจมตีเฉพาะตัวตามจังหวะของอาวุธ');
    return parts.join(' และ ');
  }
